INSERT INTO occupation (career_family_id, occupation_name, description, source, source_identifier)
SELECT cf.career_family_id, v.occupation_name, v.description, v.source, v.source_identifier
FROM (VALUES
    ('CF11', 'user experience analyst', 'User experience analysts assess client interaction and experience and analyse users'' behaviours, attitudes, and emotions about the usage of a particular product, system or service. They make proposals for the improvement of the interface and usability of products, systems or services. In doing so, they take into consideration the practical, experiential, affective, meaningful and valuable aspects of human–computer interaction and product ownership, as well as the person''s perceptions of system aspects such as utility, ease of use and efficiency, and user experience dynamics.', 'ESCO v1.2.1', 'http://data.europa.eu/esco/occupation/faed411a-f920-4100-86a8-b877928b429c'),
    ('CF11', 'user interface designer', 'User interface designers are in charge of designing user interfaces for applications and systems. They perform layout, graphics and dialogues design activities as well as adaptation activities.', 'ESCO v1.2.1', 'http://data.europa.eu/esco/occupation/96e20037-0a25-4bf6-a25e-808d1605d890'),
    ('CF10', 'user interface developer', 'User interface developers implement, code, document and maintain the interface of a software system by using front-end development technologies.', 'ESCO v1.2.1', 'http://data.europa.eu/esco/occupation/866c7813-2c03-47d7-9bdc-192cfbace57c'),
    ('CF11', 'web designer', 'Web designers are in charge of creating the visual elements, layout and other aspects such as the easiness of use of a website. They follow the different phases of a website creation from the design to the implementation until it goes live. They work side by side with front-end developers to design user interfaces that met the needs of customers and are also appealing. They are responsible of developing mock-ups and of confirming the technical feasibility of the product. They can use and put together various types of elements for the website including graphics, animations, text, videos and photos. They are in contact with clients and stakeholders of the company to ensure that the design of the website meets their needs.', 'ESCO v1.2.1', 'http://data.europa.eu/esco/occupation/30ed83ba-cc89-4d9f-a59d-5c783c1da56e'),
    ('CF10', 'web developer', 'Web developers develop, implement and document web-accessible software based on the designs provided. They align the client''s web presence with its business strategy, troubleshoot software problems and issues and look for ways to improve the application.', 'ESCO v1.2.1', 'http://data.europa.eu/esco/occupation/c40a2919-48a9-40ea-b506-1f34f693496d')
) AS v (family_code, occupation_name, description, source, source_identifier)
JOIN career_family cf ON cf.family_code = v.family_code
ON CONFLICT ON CONSTRAINT uq_occupation DO NOTHING;

